from app.core.resources import display_rows

"""Notification Delivery Attempts endpoints and their PostgreSQL queries."""

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from app.core import sql_queries as sql
from app.core.resources import staff_only
from app.core.security import require

from .service import Service

TABLE = "notification_delivery_attempts"
router = APIRouter(
    prefix="/notification-delivery-attempts", tags=["Notification Delivery Attempts"]
)


# --- PostgreSQL queries for this screen (generated by tools/generate_module_sql.py from the
# live table definitions; regenerate after schema migrations). Values are bound as %(name)s
# parameters, never formatted into the text; app.core.sql_queries runs these statements and
# keeps custom fields (record_extras) with each record. Table names resolve through the
# connection's search_path (EDUNEXA_DB_SCHEMA).

LIST_SQL = """
SELECT t.code,
       t.notification_code,
       t.reminder_code,
       t.provider,
       t.provider_message_id,
       t.attempt_number,
       t.status,
       t.attempted_at,
       t.error_code,
       x.data AS extras
FROM notification_delivery_attempts AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'notification_delivery_attempts' AND x.record_code = t.code
ORDER BY t.code
"""

GET_SQL = """
SELECT t.code,
       t.notification_code,
       t.reminder_code,
       t.provider,
       t.provider_message_id,
       t.attempt_number,
       t.status,
       t.attempted_at,
       t.error_code,
       x.data AS extras
FROM notification_delivery_attempts AS t
LEFT JOIN record_extras AS x
  ON x.table_name = 'notification_delivery_attempts' AND x.record_code = t.code
WHERE t.code = %(code)s
"""

INSERT_SQL = """
INSERT INTO notification_delivery_attempts (
    code,
    notification_code,
    reminder_code,
    provider,
    provider_message_id,
    attempt_number,
    status,
    attempted_at,
    error_code
)
VALUES (
    %(code)s,
    %(notification_code)s,
    %(reminder_code)s,
    %(provider)s,
    %(provider_message_id)s,
    %(attempt_number)s,
    %(status)s,
    COALESCE(%(attempted_at)s, CURRENT_TIMESTAMP),
    %(error_code)s
)
"""

UPDATE_SQL = """
UPDATE notification_delivery_attempts
SET notification_code = %(notification_code)s,
    reminder_code = %(reminder_code)s,
    provider = %(provider)s,
    provider_message_id = %(provider_message_id)s,
    attempt_number = %(attempt_number)s,
    status = %(status)s,
    attempted_at = %(attempted_at)s,
    error_code = %(error_code)s
WHERE code = %(code)s
"""

DELETE_SQL = """
DELETE FROM notification_delivery_attempts
WHERE code = %(code)s
"""

REFERENCED_BY_SQL = None
# --- end of generated SQL


def query_list(data):
    return sql.fetch_all(data, TABLE, LIST_SQL)


def query_get(data, code):
    record = sql.fetch_one(data, TABLE, GET_SQL, code)
    if record is None:
        raise HTTPException(404, "Record not found")
    return record


def query_save(data, record):
    return sql.save(data, TABLE, record, INSERT_SQL, UPDATE_SQL)


def query_delete(data, code):
    sql.delete(data, TABLE, DELETE_SQL, code)


def query_referenced_by(data, code):
    return sql.referenced_by(data, TABLE, REFERENCED_BY_SQL, code)


class Queries:
    table = TABLE
    list = staticmethod(query_list)
    get = staticmethod(query_get)
    save = staticmethod(query_save)
    delete = staticmethod(query_delete)
    referenced_by = staticmethod(query_referenced_by)


service = Service(Queries())


@router.get("")
def list_records(
    request: Request,
    offset: int = Query(0, ge=0),
    limit: int = Query(50, ge=1, le=200),
    user=Depends(require(TABLE, "view")),
):
    staff_only(user)
    data = request.app.state.store.snapshot()
    records = display_rows(data, TABLE, query_list(data))
    return {
        "items": records[offset : offset + limit],
        "total": len(records),
        "offset": offset,
        "limit": limit,
    }


@router.get("/{code}")
def get_record(code: str, request: Request, user=Depends(require(TABLE, "view"))):
    staff_only(user)
    return query_get(request.app.state.store.snapshot(), code)
